<header class="rp-head"><span>Administración</span><h1>Auditoría y reportes</h1><p>Indicadores institucionales y trazabilidad obtenidos desde MariaDB.</p></header><?php if($reportError):?><p class="rp-error"><?=e($reportError)?></p><?php endif;?><form class="rp-range"><label>Desde<input type="date" name="from" value="<?=e($reportFrom)?>"></label><label>Hasta<input type="date" name="to" value="<?=e($reportTo)?>"></label><input type="hidden" name="page" value="admin-reports"><button>Actualizar</button></form><section class="rp-stats"><article><strong><?=$reportData['summary']['users']?></strong><span>Usuarios creados</span></article><article><strong><?=$reportData['summary']['projects']?></strong><span>Proyectos registrados</span></article><article><strong><?=$reportData['summary']['deliveries']?></strong><span>Entregas recibidas</span></article><article><strong><?=$reportData['summary']['actions']?></strong><span>Acciones auditadas</span></article></section><div class="rp-grid"><section><h2>Usuarios por rol</h2><?php foreach($reportData['roles'] as $row):?><div class="rp-bar"><span><?=e($row['label'])?></span><strong><?=$row['total']?></strong></div><?php endforeach;?></section><section><h2>Proyectos por estado</h2><?php if(!$reportData['statuses']):?><p class="rp-empty">Sin proyectos registrados.</p><?php else:foreach($reportData['statuses'] as $row):?><div class="rp-bar"><span><?=e(ucfirst(str_replace('_',' ',$row['label'])))?></span><strong><?=$row['total']?></strong></div><?php endforeach;endif;?></section></div><section class="rp-activity"><header><h2>Actividad auditada</h2><span>Últimos 20 eventos del periodo</span></header><?php if(!$reportData['activity']):?><p class="rp-empty">No existe actividad durante estas fechas.</p><?php else:foreach($reportData['activity'] as $item):?><article><i class="fa-solid fa-shield-halved"></i><div><strong><?=e(ucfirst(str_replace('_',' ',$item['action'])))?></strong><p><?=e($item['actor']?:'Sistema')?> · <?=e($item['entity_type'])?></p></div><time><?=e(date('d/m/Y H:i',strtotime($item['created_at'])))?></time></article><?php endforeach;endif;?></section><section class="rp-exports"><div><h2>Exportar información</h2><p>Archivos CSV compatibles con hojas de cálculo.</p></div><nav><a href="<?=e(route('admin-report-export').'&type=users&from='.$reportFrom.'&to='.$reportTo)?>"><i class="fa-solid fa-users"></i> Usuarios</a><a href="<?=e(route('admin-report-export').'&type=projects&from='.$reportFrom.'&to='.$reportTo)?>"><i class="fa-solid fa-folder-open"></i> Proyectos</a><a href="<?=e(route('admin-report-export').'&type=audit&from='.$reportFrom.'&to='.$reportTo)?>"><i class="fa-solid fa-clock-rotate-left"></i> Auditoría</a></nav></section>
